30	type nativeProviderResolution struct {
31		Provider agentcore.Provider
32		Name     string
33		Entry    ServiceProviderEntry
34	}
35	
36	func (s *service) resolveConfiguredNativeProvider(req ServiceExecuteRequest) nativeProviderResolution {
37		sc := s.opts.ServiceConfig
38		if sc == nil {
39			return nativeProviderResolution{}
40		}
41		unreachableProviders := s.getUnreachableProvidersForNativeResolution()
42		name, entry, ok := selectConfiguredNativeProviderWithReachability(sc, req, unreachableProviders)
43		if !ok {
44			return nativeProviderResolution{}
45		}
46		if req.Model != "" {
47			entry.Model = req.Model
48		}
49		provider := s.buildNativeProvider(name, entry)
50		if provider == nil {
51			return nativeProviderResolution{Name: name, Entry: entry}
52		}
53		return nativeProviderResolution{Provider: provider, Name: name, Entry: entry}
54	}
55	
56	func selectConfiguredNativeProvider(sc ServiceConfig, req ServiceExecuteRequest) (string, ServiceProviderEntry, bool) {
57		return selectConfiguredNativeProviderWithReachability(sc, req, nil)
58	}
59	
60	func selectConfiguredNativeProviderWithReachability(sc ServiceConfig, req ServiceExecuteRequest, unreachableProviders map[string]bool) (string, ServiceProviderEntry, bool) {
61		if req.Provider != "" {
62			if entry, ok := sc.Provider(req.Provider); ok {
63				return req.Provider, entry, true
64			}
65			if name, entry, ok := selectConfiguredEndpointProvider(sc, req.Provider); ok {
66				return name, entry, true
67			}
68		}
69	
70		wantedType := requestedNativeProviderType(req)
71		if wantedType != "" {
72			if name := sc.DefaultProviderName(); name != "" {
73				if entry, ok := sc.Provider(name); ok && normalizeServiceProviderType(entry.Type) == wantedType {
74					return name, entry, true
75				}
76			}
77			for _, name := range sc.ProviderNames() {
78				entry, ok := sc.Provider(name)
79				if ok && normalizeServiceProviderType(entry.Type) == wantedType {
80					return name, entry, true
81				}
82			}
83		}
84	
85		if req.Provider == "" && wantedType == "" {
86			name := sc.DefaultProviderName()
87			if name == "" {
88				return "", ServiceProviderEntry{}, false
89			}
90			if unreachableProviders != nil && unreachableProviders[name] {
91				return "", ServiceProviderEntry{}, false
92			}
93			entry, ok := sc.Provider(name)
94			return name, entry, ok
95		}
96	
97		return "", ServiceProviderEntry{}, false
98	}
99	
100	func selectConfiguredEndpointProvider(sc ServiceConfig, ref string) (string, ServiceProviderEntry, bool) {
101		providerName, endpointName, ok := splitEndpointProviderRef(ref)
102		if !ok {
103			return "", ServiceProviderEntry{}, false
104		}
105		entry, ok := sc.Provider(providerName)
106		if !ok {
107			return "", ServiceProviderEntry{}, false
108		}
109		for _, endpoint := range modelDiscoveryEndpoints(entry) {
110			if endpoint.Name != endpointName {
111				continue
112			}
113			entry.BaseURL = endpoint.BaseURL
114			entry.ServerInstance = endpoint.ServerInstance
115			entry.Endpoints = []ServiceProviderEndpoint{{Name: endpoint.Name, BaseURL: endpoint.BaseURL}}
116			return ref, entry, true
117		}
118		return "", ServiceProviderEntry{}, false
119	}
120	
121	func endpointProviderRef(providerName, endpointName string) string {
122		if endpointName == "" {
123			return providerName
124		}
125		return providerName + "@" + endpointName
126	}
127	
128	func splitEndpointProviderRef(ref string) (string, string, bool) {
129		providerName, endpointName, ok := strings.Cut(ref, "@")
130		if !ok || providerName == "" || endpointName == "" {
131			return "", "", false
132		}
133		return providerName, endpointName, true
134	}
135	
136	func requestedNativeProviderType(req ServiceExecuteRequest) string {
137		if req.Provider != "" {
138			return normalizeServiceProviderType(req.Provider)
139		}
140		switch req.Harness {
141		case "", "fiz":
142			return ""
143		default:
144			return normalizeServiceProviderType(req.Harness)
145		}
146	}
147	
148	func (s *service) nativeProviderNotConfiguredError(req ServiceExecuteRequest, decision RouteDecision) string {
149		wantedType := requestedNativeProviderType(req)
150		if wantedType == "" {
151			errMsg := "orphan model: " + decision.Model
152			if decision.Model == "" {
153				errMsg = "no provider configured for native harness"
154			}
155			return errMsg
156		}
157		available := s.availableProviderTypes()
158		harness := decision.Harness
159		if harness == "" {
160			harness = "fiz"
161		}
162		return fmt.Sprintf("harness %q: no configured provider matches type %q (available: %s)", harness, wantedType, available)
163	}
164	
165	func (s *service) availableProviderTypes() string {
166		sc := s.opts.ServiceConfig
167		if sc == nil {
168			return "[]"
169		}
170		var parts []string
171		for _, name := range sc.ProviderNames() {
172			entry, ok := sc.Provider(name)
173			if !ok {
174				continue
175			}
176			parts = append(parts, fmt.Sprintf("%s (%s)", name, normalizeServiceProviderType(entry.Type)))
177		}
178		if len(parts) == 0 {
179			return "[]"
180		}
181		return "[" + strings.Join(parts, ", ") + "]"
182	}
