184	// buildNativeProvider is the service-time factory. Per agent-8e4eb44c
185	// the per-type switch is gone; both this and internal/config's
186	// BuildProvider go through registry.Lookup. Adding a new provider type
187	// is one Register() call in the new package; no edits to this file
188	// or internal/config/config.go's factory.
189	func (s *service) buildNativeProvider(name string, entry ServiceProviderEntry) agentcore.Provider {
190		if entry.ConfigError != "" {
191			return nil
192		}
193		typ := normalizeServiceProviderType(entry.Type)
194		if d, ok := registry.Lookup(typ); ok {
195			return d.Factory(registry.Inputs{
196				ProviderName:        name,
197				BaseURL:             entry.BaseURL,
198				APIKey:              entry.APIKey,
199				Model:               entry.Model,
200				ModelReasoningWire:  nativeModelReasoningWireMap(),
201				QuotaSignalObserver: s.quotaSignalObserver(name),
202			})
203		}
204		return nil
205	}
206	
207	// quotaSignalObserver returns a callback that updates the provider quota
208	// state machine when a parsed rate-limit signal indicates the provider's
209	// subscription/daily cap has been hit (or imminently will be). Returns nil
210	// when the service has no quota store, which makes the provider middleware
211	// a no-op.
212	func (s *service) quotaSignalObserver(providerName string) func(quotaheaders.Signal) {
213		if s == nil || s.providerQuota == nil || providerName == "" {
214			return nil
215		}
216		store := s.providerQuota
217		return func(signal quotaheaders.Signal) {
218			now := time.Now()
219			exhausted, retryAt := signal.IsExhausted(now)
220			if !exhausted {
221				return
222			}
223			if retryAt.IsZero() {
224				// Provider said "exhausted" but gave us no reset window. Fall
225				// back to a short cooldown so we don't peg the provider in the
226				// excluded set forever; the next response will refresh us.
227				retryAt = now.Add(time.Minute)
228			}
229			store.MarkQuotaExhausted(providerName, retryAt)
230		}
231	}
232	
233	// nativeModelReasoningWireMap returns the catalog reasoning_wire map for use
234	// by the native (service-side) provider builder. Models without an explicit
235	// reasoning_wire are omitted; the provider treats absence as the "provider"
236	// default.
237	func nativeModelReasoningWireMap() map[string]string {
238		cat, err := modelcatalog.Default()
239		if err != nil {
240			return nil
241		}
242		all := cat.AllModels()
243		if len(all) == 0 {
244			return nil
245		}
246		out := make(map[string]string, len(all))
247		for id, entry := range all {
248			if entry.ReasoningWire != "" {
249				out[id] = entry.ReasoningWire
250			}
251		}
252		return out
253	}
254	
255	func (s *service) getUnreachableProvidersForNativeResolution() map[string]bool {
256		if s == nil || s.providerProbe == nil {
257			return nil
258		}
259		unreachable := make(map[string]bool)
260		if s.opts.ServiceConfig == nil {
261			return unreachable
262		}
263		for _, name := range s.opts.ServiceConfig.ProviderNames() {
264			if r, ok := s.providerProbe.LastProbe(name, ""); ok && !r.LastProbeSuccess {
265				unreachable[name] = true
266			}
267		}
268		if len(unreachable) == 0 {
269			return nil
270		}
271		return unreachable
272	}
