24	// ResolveRoute resolves an under-specified RouteRequest to a concrete
25	// (Harness, Provider, Model) decision per CONTRACT-003.
26	//
27	// The implementation delegates to internal/routing.Resolve — the single
28	// routing engine that consolidates DDx-side harness-tier ranking and
29	// fiz-side provider failover ordering.
30	func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
31		if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
32			return nil, err
33		}
34		if err := ValidateRole(req.Role); err != nil {
35			return nil, err
36		}
37		if err := ValidateCorrelationID(req.CorrelationID); err != nil {
38			return nil, err
39		}
40		if req.Harness != "" && req.Model != "" {
41			canonical := harnesses.ResolveHarnessAlias(req.Harness)
42			if !s.registry.Has(canonical) {
43				return nil, fmt.Errorf("unknown harness %q", req.Harness)
44			}
45			cfg, _ := s.registry.Get(canonical)
46			if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
47				return nil, err
48			}
49		}
50		if req.Harness != "" && req.Policy != "" {
51			canonical := harnesses.ResolveHarnessAlias(req.Harness)
52			if !s.registry.Has(canonical) {
53				return nil, fmt.Errorf("unknown harness %q", req.Harness)
54			}
55			cfg, _ := s.registry.Get(canonical)
56			if err := validateExplicitHarnessPolicy(canonical, cfg, req.Policy); err != nil {
57				return nil, err
58			}
59		}
60		cat := serviceRoutingCatalog()
61		requestedPolicy := req.Policy
62		policy := routingPolicyForName(cat, requestedPolicy)
63		powerPolicy := routePowerPolicyForRequest(cat, req)
64		providerPreference, err := providerPreferenceForPolicy(cat, requestedPolicy)
65		if err != nil {
66			return &RouteDecision{
67				RequestedPolicy: req.Policy,
68				PowerPolicy:     powerPolicy,
69			}, err
70		}
71		in, snapshot := s.buildRoutingInputsWithCatalog(ctx, cat, modelsnapshot.RefreshBackground)
72	
73		resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
74		if modelErr != nil {
75			result := &RouteDecision{
76				RequestedPolicy: req.Policy,
77				PowerPolicy:     powerPolicy,
78				Candidates:      modelCandidates,
79			}
80			s.annotateRouteDecisionEvidence(result)
81			return result, publicRoutingError(modelErr, result.Candidates, req.Policy)
82		}
83	
84		rReq := routing.Request{
85			Policy:                policy,
86			Model:                 resolvedModel,
87			Provider:              req.Provider,
88			Harness:               req.Harness,
89			Reasoning:             effectiveReasoningString(req.Reasoning),
90			Permissions:           req.Permissions,
91			ProviderPreference:    providerPreference,
92			EstimatedPromptTokens: req.EstimatedPromptTokens,
93			RequiresTools:         req.RequiresTools,
94			CorrelationID:         req.CorrelationID,
95			AllowLocal:            req.AllowLocal,
96			Require:               append([]string(nil), req.Require...),
97			ExcludedRoutes:        publicToRoutingExcludedRoutes(req.ExcludedRoutes),
98		}
99		if policyEntry, _, ok := policyForName(cat, requestedPolicy); ok {
100			rReq.AllowLocal = rReq.AllowLocal || policyEntry.AllowLocal
101			rReq.Require = append(append([]string(nil), policyEntry.Require...), rReq.Require...)
102		}
103		rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
104		s.applyRouteAttemptCooldowns(&in)
105		dec, err := routing.Resolve(rReq, in)
106		if err != nil {
107			if escalated, edec, eerr := escalatePolicyLadder(rReq, in, err, req.Policy); escalated {
108				dec = edec
109				err = eerr
110			}
111		}
112		result := routeDecisionFromInternal(dec, powerPolicy)
113		if err != nil {
114			if result == nil {
115				result = &RouteDecision{}
116			}
117			result.RequestedPolicy = req.Policy
118			result.PowerPolicy = powerPolicy
119			s.annotateRouteDecisionEvidence(result)
120			s.annotateOpenrouterCreditFreshness(result)
121			return result, publicRoutingError(err, result.Candidates, req.Policy)
122		}
123		s.applyStickyRouteLease(req.CorrelationID, result)
124		if result != nil && result.Endpoint == "" {
125			_, endpoint, _ := splitEndpointProviderRef(result.Provider)
126			result.Endpoint = endpoint
127		}
128		s.annotateRouteDecisionSnapshotEvidence(result, snapshot)
129		s.annotateRouteDecisionEvidence(result)
130		s.annotateOpenrouterCreditFreshness(result)
131		// Cache the decision so RouteStatus can surface LastDecision.
132		if result != nil {
133			result.RequestedPolicy = req.Policy
134			result.PowerPolicy = powerPolicy
135			result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
136			result.Power = catalogPowerForModel(cat, result.Model)
137		}
138		s.cacheRouteDecision(req.Model, result)
139		return result, nil
140	}
141	
142	func routeDecisionFromInternal(dec *routing.Decision, powerPolicy RoutePowerPolicy) *RouteDecision {
143		if dec == nil {
144			return nil
145		}
146		return &RouteDecision{
147			Harness:        dec.Harness,
148			Provider:       dec.Provider,
149			Endpoint:       dec.Endpoint,
150			ServerInstance: dec.ServerInstance,
151			Model:          dec.Model,
152			Reason:         dec.Reason,
153			Candidates:     routeCandidatesFromInternal(dec.Candidates, powerPolicy),
154		}
155	}
156	
157	func routeCandidatesFromInternal(candidates []routing.Candidate, powerPolicy RoutePowerPolicy) []RouteCandidate {
158		if len(candidates) == 0 {
159			return nil
160		}
161		out := make([]RouteCandidate, len(candidates))
162		for i, candidate := range candidates {
163			out[i] = routeCandidateFromInternal(candidate, powerPolicy)
164		}
165		return out
166	}
167	
168	func routeCandidateFromInternal(candidate routing.Candidate, powerPolicy RoutePowerPolicy) RouteCandidate {
169		components := RouteCandidateComponents{
170			Power:            candidate.Power,
171			Cost:             candidate.CostUSDPer1kTokens,
172			CostClass:        candidate.CostClass,
173			LatencyMS:        candidate.LatencyMS,
174			SpeedTPS:         candidate.SpeedTPS,
175			Utilization:      candidate.Utilization,
176			SuccessRate:      candidate.SuccessRate,
177			QuotaOK:          candidate.QuotaOK,
178			QuotaPercentUsed: candidate.QuotaPercentUsed,
179			QuotaTrend:       candidate.QuotaTrend,
180			Capability:       capabilityScoreForCostClass(candidate.CostClass),
181			ContextHeadroom:  candidate.ContextHeadroom,
182			StickyAffinity:   candidate.StickyAffinity,
183		}
184		powerHintFit := scorePowerHintFit(candidate, powerPolicy)
185		scorePower := candidate.ScoreComponents["power"]
186		scoreCost := candidate.ScoreComponents["cost"]
187		scorePerformance := candidate.ScoreComponents["performance"]
188		scoreLocality := candidate.ScoreComponents["deployment_locality"]
189		scoreQuota := candidate.ScoreComponents["quota_health"]
190		scoreUtilization := candidate.ScoreComponents["utilization"]
191		components.PowerHintFit = powerHintFit
192		components.PowerWeightedCapability = scorePower - powerHintFit + positiveScorePart(scoreCost)
193		components.LatencyWeight = positiveScorePart(scorePerformance)
194		components.StaleSignalPenalty = positiveScorePart(-scorePerformance)
195		components.PlacementBonus = scoreLocality + candidate.StickyAffinity
196		components.QuotaBonus = positiveScorePart(scoreQuota)
197		components.MarginalCostPenalty = positiveScorePart(-scoreCost)
198		components.AvailabilityPenalty = positiveScorePart(-scoreQuota) + positiveScorePart(-scoreUtilization)
199		return RouteCandidate{
200			Harness:             candidate.Harness,
201			Provider:            candidate.Provider,
202			Billing:             candidate.Billing,
203			ActualCashSpend:     candidate.ActualCashSpend,
204			Endpoint:            candidate.Endpoint,
205			ServerInstance:      candidate.ServerInstance,
206			Model:               candidate.Model,
207			Score:               candidate.Score,
208			CostUSDPer1kTokens:  candidate.CostUSDPer1kTokens,
209			CostSource:          candidate.CostSource,
210			EffectiveCost:       candidate.CostUSDPer1kTokens,
211			EffectiveCostSource: candidate.CostSource,
212			Eligible:            candidate.Eligible,
213			Reason:              candidate.Reason,
214			FilterReason:        publicFilterReason(candidate),
215			ContextLength:       candidate.ContextLength,
216			ContextSource:       candidate.ContextSource,
217			Components:          components,
218			ScoreComponents:     copyScoreComponents(candidate.ScoreComponents),
219		}
220	}
221	
222	func copyScoreComponents(in map[string]float64) map[string]float64 {
223		if len(in) == 0 {
224			return nil
225		}
226		out := make(map[string]float64, len(in))
227		for k, v := range in {
228			out[k] = v
229		}
230		return out
231	}
232	
233	func scorePowerHintFit(candidate routing.Candidate, policy RoutePowerPolicy) float64 {
234		power := candidate.Power
235		if power <= 0 {
236			return 0
237		}
238		if policy.MaxPower > 0 && candidate.FilterReason == routing.FilterReasonAboveMaxPower && candidate.ScoreComponents != nil {
239			return candidate.ScoreComponents["power"]
240		}
241		if policy.MinPower > 0 && power < policy.MinPower {
242			// Mirror the engine scorer: materially underpowered routes should not
243			// win just because they are cheap.
244			return -float64(policy.MinPower-power) * 12
245		}
246		if policy.MaxPower > 0 && power > policy.MaxPower {
247			return -float64(power - policy.MaxPower)
248		}
249		return 0
250	}
251	
252	func positiveScorePart(v float64) float64 {
253		if v > 0 {
254			return v
255		}
256		return 0
257	}
