259	type routeSnapshotCandidateKey struct {
260		Provider       string
261		Endpoint       string
262		ServerInstance string
263		Model          string
264	}
265	
266	func routeSnapshotCandidateIndex(snapshot modelsnapshot.ModelSnapshot) map[routeSnapshotCandidateKey]modelsnapshot.KnownModel {
267		if len(snapshot.Models) == 0 {
268			return nil
269		}
270		out := make(map[routeSnapshotCandidateKey]modelsnapshot.KnownModel, len(snapshot.Models))
271		for _, row := range snapshot.Models {
272			key := routeSnapshotCandidateKey{
273				Provider:       strings.TrimSpace(row.Provider),
274				Endpoint:       strings.TrimSpace(row.EndpointName),
275				ServerInstance: strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance)),
276				Model:          strings.TrimSpace(row.ID),
277			}
278			if key.Provider == "" || key.Model == "" {
279				continue
280			}
281			if _, exists := out[key]; exists {
282				continue
283			}
284			out[key] = row
285		}
286		return out
287	}
288	
289	func routeSnapshotEvidenceForCandidate(candidate RouteCandidate, snapshot modelsnapshot.ModelSnapshot) (modelsnapshot.KnownModel, bool) {
290		index := routeSnapshotCandidateIndex(snapshot)
291		if len(index) == 0 {
292			return modelsnapshot.KnownModel{}, false
293		}
294		provider := strings.TrimSpace(candidate.Provider)
295		endpoint := strings.TrimSpace(candidate.Endpoint)
296		serverInstance := strings.TrimSpace(candidate.ServerInstance)
297		model := strings.TrimSpace(candidate.Model)
298		if base, ep, ok := splitEndpointProviderRef(provider); ok {
299			provider = base
300			if endpoint == "" {
301				endpoint = ep
302			}
303		}
304		keys := []routeSnapshotCandidateKey{{
305			Provider:       provider,
306			Endpoint:       endpoint,
307			ServerInstance: serverInstance,
308			Model:          model,
309		}}
310		if endpoint == "" {
311			keys = append(keys, routeSnapshotCandidateKey{
312				Provider:       provider,
313				ServerInstance: serverInstance,
314				Model:          model,
315			})
316		}
317		if serverInstance == "" {
318			keys = append(keys, routeSnapshotCandidateKey{
319				Provider: provider,
320				Endpoint: endpoint,
321				Model:    model,
322			})
323			if endpoint == "" {
324				keys = append(keys, routeSnapshotCandidateKey{
325					Provider: provider,
326					Model:    model,
327				})
328			}
329		}
330		for _, key := range keys {
331			if row, ok := index[key]; ok {
332				return row, true
333			}
334		}
335		for _, row := range snapshot.Models {
336			rowProvider := strings.TrimSpace(row.Provider)
337			rowEndpoint := strings.TrimSpace(row.EndpointName)
338			rowServerInstance := strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance))
339			if rowProvider != provider || strings.TrimSpace(row.ID) != model {
340				continue
341			}
342			if endpoint != "" && rowEndpoint != endpoint {
343				continue
344			}
345			if serverInstance != "" && rowServerInstance != serverInstance {
346				continue
347			}
348			return row, true
349		}
350		return modelsnapshot.KnownModel{}, false
351	}
