1205	// providerQuotaExhaustedUntil snapshots the per-provider quota state machine
1206	// at the given instant for the routing engine. Returns nil when no provider
1207	// is currently in quota_exhausted state, which keeps the routing path
1208	// allocation-free in the common case.
1209	func (s *service) providerQuotaExhaustedUntil(now time.Time) map[string]time.Time {
1210		if s == nil || s.providerQuota == nil {
1211			return nil
1212		}
1213		return s.providerQuota.ExhaustedAt(now)
1214	}
