1456	// catalogTierModelsForHarnessSurface enumerates the active concrete tier IDs
1457	// the catalog publishes for a harness surface, sorted deterministically by
1458	// power (descending) then by ID. Returns nil when the surface is unknown to
1459	// the catalog or the catalog has no active models on that surface.
1460	func catalogTierModelsForHarnessSurface(cat *modelcatalog.Catalog, harnessSurface string) []string {
1461		if cat == nil {
1462			return nil
1463		}
1464		catalogSurface, ok := serviceRoutingCatalogSurface(harnessSurface)
1465		if !ok {
1466			return nil
1467		}
1468		concrete := cat.AllConcreteModels(catalogSurface)
1469		if len(concrete) == 0 {
1470			return nil
1471		}
1472		ids := make([]string, 0, len(concrete))
1473		for id := range concrete {
1474			ids = append(ids, id)
1475		}
1476		sort.Slice(ids, func(i, j int) bool {
1477			pi, _, _ := catalogPowerEligibility(cat, ids[i])
1478			pj, _, _ := catalogPowerEligibility(cat, ids[j])
1479			if pi != pj {
1480				return pi > pj
1481			}
1482			return ids[i] < ids[j]
1483		})
1484		return ids
1485	}
