1504	// buildProviderContextWindows assembles the ContextWindows map for a
1505	// ProviderEntry from the model catalog. Entries are added for the provider's
1506	// configured DefaultModel and every DiscoveredID that has a non-zero
1507	// context_window declared in the catalog. Models the catalog does not know
1508	// about are omitted (engine treats missing entries as unknown context).
1509	func buildProviderContextWindows(ctx context.Context, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog, discoveredIDs []string) (map[string]int, map[string]string) {
1510		out := make(map[string]int)
1511		sources := make(map[string]string)
1512		if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
1513			if length, source := resolveContextEvidence(ctx, pcfg, defaultModel, cat); length > 0 {
1514				out[defaultModel] = length
1515				sources[defaultModel] = source
1516			}
1517		}
1518		for _, id := range discoveredIDs {
1519			if id == "" {
1520				continue
1521			}
1522			if _, exists := out[id]; exists {
1523				continue
1524			}
1525			if length, source := resolveContextEvidence(ctx, pcfg, id, cat); length > 0 {
1526				out[id] = length
1527				sources[id] = source
1528			}
1529		}
1530		if len(out) == 0 {
1531			return nil, nil
1532		}
1533		return out, sources
1534	}
