1708	func catalogCostUSDPer1kTokens(cat *modelcatalog.Catalog, modelID string) (float64, bool) {
1709		if cat == nil || strings.TrimSpace(modelID) == "" {
1710			return 0, false
1711		}
1712		entry, ok := cat.LookupModel(modelID)
1713		if !ok {
1714			resolved := resolveCatalogCostModel(cat, modelID)
1715			if resolved == "" {
1716				return 0, false
1717			}
1718			entry, ok = cat.LookupModel(resolved)
1719			if !ok {
1720				return 0, false
1721			}
1722		}
1723		input := entry.CostInputPerM
1724		if input == 0 {
1725			input = entry.CostInputPerMTok
1726		}
1727		output := entry.CostOutputPerM
1728		if output == 0 {
1729			output = entry.CostOutputPerMTok
1730		}
1731		switch {
1732		case input > 0 && output > 0:
1733			return ((input + output) / 2) / 1000, true
1734		case input > 0:
1735			return input / 1000, true
1736		case output > 0:
1737			return output / 1000, true
1738		default:
1739			return 0, false
1740		}
1741	}
