1747			modelcatalog.SurfaceCodex,
1748			modelcatalog.SurfaceClaudeCode,
1749			modelcatalog.SurfaceGemini,
1750		} {
1751			resolved, err := cat.Resolve(ref, modelcatalog.ResolveOptions{
1752				Surface:         surface,
1753				AllowDeprecated: true,
1754			})
1755			if err == nil && resolved.ConcreteModel != "" {
1756				return resolved.ConcreteModel
1757			}
1758		}
1759		return ""
1760	}
