167	func (s *service) resolveExecuteRouteContext(ctx context.Context, req ServiceExecuteRequest) (*RouteDecision, error) {
168		// If Harness is omitted, route through the engine. The engine defaults to
169		// local-first and auto-selects from configured endpoints when no other
170		// constraints are specified — an empty request is valid if providers exist.
171		if req.Harness == "" {
172			return s.resolveExecuteRouteWithEngine(ctx, req)
173		}
174		canonical := harnesses.ResolveHarnessAlias(req.Harness)
175		if !s.registry.Has(canonical) {
176			return nil, fmt.Errorf("unknown harness %q", req.Harness)
177		}
178		cfg, _ := s.registry.Get(canonical)
179	
180		// Run per-field validators first so callers get the most specific error.
181		// Empty-model routing checks run after these, right before model resolution.
182		if err := validateExplicitHarnessPolicy(canonical, cfg, req.Policy); err != nil {
183			return nil, err
184		}
185		if err := validateExplicitProvider(s.opts.ServiceConfig, cfg, req.Provider); err != nil {
186			return nil, err
187		}
188		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
189			return nil, err
190		}
191		if err := validateExplicitHarnessReasoning(canonical, cfg, req.Reasoning); err != nil {
192			return nil, err
193		}
194		if err := validateExplicitHarnessQuota(canonical, cfg); err != nil {
195			return nil, err
196		}
197	
198		// Empty-model routing: only applies to subprocess harnesses with concrete
199		// model semantics. TestOnly (virtual/script), HTTP-provider (openrouter/
200		// lmstudio/etc.), and "fiz" harnesses skip this block — they either use
201		// DefaultModel directly or have provider-side model semantics.
202		if !cfg.TestOnly && !cfg.IsHTTPProvider && canonical != "fiz" && req.Model == "" {
203			if req.Policy == "" && req.MinPower == 0 {
204				// Under-specified: no model, no routing inputs → silent empty model
205				// avoided by failing early with a clear diagnostic.
206				return nil, fmt.Errorf("under-specified routing for harness=%q: "+
207					"supply --model, --policy, or --min-power", canonical)
208			}
209			// Policy or MinPower present: run the routing engine within the
210			// harness's eligible models. Class 2 harnesses (AutoRoutingEligible=false:
211			// gemini, opencode, pi) require an explicit --model.
212			if !cfg.AutoRoutingEligible {
213				return nil, fmt.Errorf("no auto-resolution available for harness=%q: "+
214					"harness does not support auto-routing; supply an explicit --model", canonical)
215			}
216			return s.resolveExecuteRouteWithEngine(ctx, req)
217		}
218	
219		resolvedModel := resolveSubprocessModelAlias(canonical, req.Model)
220		decision := &RouteDecision{
221			Harness:  canonical,
222			Provider: req.Provider,
223			Model:    resolvedModel,
224			Reason:   "explicit",
225			Power:    catalogPowerForModel(serviceRoutingCatalog(), resolvedModel),
226		}
227		if decision.Endpoint == "" {
228			_, endpoint, _ := splitEndpointProviderRef(decision.Provider)
229			decision.Endpoint = endpoint
230		}
231		return decision, nil
232	}
