234	func validateExplicitHarnessQuota(name string, cfg harnesses.HarnessConfig) error {
235		if harnessPaymentKind(name, cfg) != modelcatalog.BillingModelSubscription {
236			return nil
237		}
238		now := time.Now()
239		qs, ok := subscriptionQuotaForHarness(name, now)
240		if !ok || !qs.Present || !qs.Fresh || qs.OK {
241			return nil
242		}
243		return explicitQuotaUnavailable(name, qs.Windows, now)
244	}
245	
246	func explicitQuotaUnavailable(name string, windows []harnesses.QuotaWindow, now time.Time) error {
247		retryAfter := earliestQuotaResetAfter(windows, now)
248		if retryAfter.IsZero() {
249			retryAfter = now.Add(defaultQuotaRecoveryFallbackInterval)
250		}
251		return &NoViableProviderForNow{
252			RetryAfter:         retryAfter,
253			ExhaustedProviders: []string{name},
254		}
255	}
256	
257	func earliestQuotaResetAfter(windows []harnesses.QuotaWindow, now time.Time) time.Time {
258		var earliest time.Time
259		for _, window := range windows {
260			if window.ResetsAtUnix <= 0 {
261				continue
262			}
263			reset := time.Unix(window.ResetsAtUnix, 0)
264			if !reset.After(now) {
265				continue
266			}
267			if earliest.IsZero() || reset.Before(earliest) {
268				earliest = reset
269			}
270		}
271		return earliest
272	}
