package fizeau

import (
	"context"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/routehealth"
)

// TestDefaultProviderFailsOverWhenUnreachable verifies that when the
// default_provider endpoint is unreachable, ResolveRoute selects an
// available candidate (e.g., subscription harness) instead of timing out.
func TestDefaultProviderFailsOverWhenUnreachable(t *testing.T) {
	cacheRoot := t.TempDir()
	t.Setenv("FIZEAU_CACHE_DIR", cacheRoot)
	cache := &discoverycache.Cache{Root: cacheRoot}

	modelID := "mlx-community/Qwen3.6-27B-8bit"
	deadURL := "http://lmstudio-dead:8000/v1"
	capturedAt := time.Date(2026, 5, 28, 12, 0, 0, 0, time.UTC)

	// Write a discovery snapshot for the dead provider (it was discovered before it went down).
	writeSnapshotDiscoveryFixture(t, cache,
		testDiscoverySourceName("lmstudio-dead", "lmstudio-dead", deadURL, "lmstudio-dead"),
		capturedAt,
		[]string{modelID},
	)

	// Catalog with power policy for testing.
	catalog := loadRoutingFixtureCatalog(t, `
version: 5
generated_at: 2026-05-28T00:00:00Z
catalog_version: test
policies:
  default:
    min_power: 1
    max_power: 10
    allow_local: true
models:
  mlx-community/Qwen3.6-27B-8bit:
    family: qwen
    status: active
    power: 7
    context_window: 32768
    surfaces:
      embedded-openai: mlx-community/Qwen3.6-27B-8bit
`)
	t.Cleanup(replaceRoutingCatalogForTest(t, catalog))

	// Service with lmstudio-dead as default provider.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"lmstudio-dead": {
				Type:           "rapid-mlx",
				BaseURL:        deadURL,
				ServerInstance: "lmstudio-dead",
				Model:          modelID,
			},
		},
		names:       []string{"lmstudio-dead"},
		defaultName: "lmstudio-dead",
	}

	// Codex is available as a subscription harness.
	configureFreshCodexQuotaForRouting(t)

	svc := newResolveRouteProbeTestService(t, sc, func(_ context.Context, provider, _ string) bool {
		t.Fatalf("route hot path invoked aliveness prober for %s", provider)
		return false
	})
	makeOnlyCodexSubprocessAvailable(svc)

	now := time.Now().UTC()
	// Record that lmstudio-dead failed its probe.
	svc.providerProbe.RecordProbe("lmstudio-dead", "", false, now)

	// Call ResolveRoute with an unpinned request (no --harness/--provider/--model).
	dec, err := svc.ResolveRoute(context.Background(), RouteRequest{})
	if err != nil {
		t.Fatalf("ResolveRoute: %v", err)
	}
	if dec == nil {
		t.Fatal("ResolveRoute returned nil decision")
	}

	// Should pick codex (subscription harness), NOT lmstudio-dead (dead default provider).
	if dec.Harness != "codex" {
		t.Fatalf("decision.Harness=%q, want codex; decision=%#v", dec.Harness, dec)
	}

	// Verify that lmstudio-dead is in candidates but marked as ineligible.
	var sawDead bool
	for _, candidate := range dec.Candidates {
		if candidate.Provider != "lmstudio-dead" {
			continue
		}
		sawDead = true
		if candidate.Eligible {
			t.Fatalf("lmstudio-dead candidate should not be eligible; candidate=%#v", candidate)
		}
		if candidate.FilterReason != FilterReasonEndpointUnreachable {
			t.Fatalf("lmstudio-dead FilterReason=%q, want %q", candidate.FilterReason, FilterReasonEndpointUnreachable)
		}
	}
	if !sawDead && len(dec.Candidates) > 0 {
		// It's OK if lmstudio-dead doesn't appear as a candidate at all, as long as
		// we successfully routed to codex.
		t.Logf("lmstudio-dead did not appear as candidate (acceptable if routing succeeded)")
	}
}

// TestDefaultProviderUsedWhenReachable verifies no regression: when the
// default_provider IS reachable, it is still selected for unpinned native requests.
func TestDefaultProviderUsedWhenReachable(t *testing.T) {
	cacheRoot := t.TempDir()
	t.Setenv("FIZEAU_CACHE_DIR", cacheRoot)
	cache := &discoverycache.Cache{Root: cacheRoot}

	modelID := "mlx-community/Qwen3.6-27B-8bit"
	lmstudioURL := "http://lmstudio:8000/v1"
	capturedAt := time.Date(2026, 5, 28, 12, 0, 0, 0, time.UTC)

	// Write a discovery snapshot for the healthy provider.
	writeSnapshotDiscoveryFixture(t, cache,
		testDiscoverySourceName("lmstudio", "lmstudio", lmstudioURL, "lmstudio"),
		capturedAt,
		[]string{modelID},
	)

	// Catalog with power policy for testing.
	catalog := loadRoutingFixtureCatalog(t, `
version: 5
generated_at: 2026-05-28T00:00:00Z
catalog_version: test
policies:
  default:
    min_power: 1
    max_power: 10
    allow_local: true
models:
  mlx-community/Qwen3.6-27B-8bit:
    family: qwen
    status: active
    power: 7
    context_window: 32768
    surfaces:
      embedded-openai: mlx-community/Qwen3.6-27B-8bit
`)
	t.Cleanup(replaceRoutingCatalogForTest(t, catalog))

	// Service with lmstudio as default provider.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"lmstudio": {
				Type:           "rapid-mlx",
				BaseURL:        lmstudioURL,
				ServerInstance: "lmstudio",
				Model:          modelID,
			},
		},
		names:       []string{"lmstudio"},
		defaultName: "lmstudio",
	}

	svc := newResolveRouteProbeTestService(t, sc, func(_ context.Context, provider, _ string) bool {
		t.Fatalf("route hot path invoked aliveness prober for %s", provider)
		return false
	})

	now := time.Now().UTC()
	// Record that lmstudio succeeded its probe.
	svc.providerProbe.RecordProbe("lmstudio", "", true, now)

	// Call ResolveRoute with an unpinned request.
	dec, err := svc.ResolveRoute(context.Background(), RouteRequest{})
	if err != nil {
		t.Fatalf("ResolveRoute: %v", err)
	}
	if dec == nil {
		t.Fatal("ResolveRoute returned nil decision")
	}

	// Should pick lmstudio (the reachable default provider).
	if dec.Provider != "lmstudio" {
		t.Fatalf("decision.Provider=%q, want lmstudio; decision=%#v", dec.Provider, dec)
	}
}

// TestDefaultProviderNotPinnedWhenUnreachableMultipleCandidates verifies that
// an unpinned request with an unreachable default and multiple other candidates
// doesn't timeout but successfully routes to the best scoring candidate.
func TestDefaultProviderNotPinnedWhenUnreachableMultipleCandidates(t *testing.T) {
	cacheRoot := t.TempDir()
	t.Setenv("FIZEAU_CACHE_DIR", cacheRoot)
	cache := &discoverycache.Cache{Root: cacheRoot}

	modelID := "mlx-community/Qwen3.6-27B-8bit"
	deadURL := "http://lmstudio-dead:8000/v1"
	vidarURL := "http://vidar:8001/v1"
	capturedAt := time.Date(2026, 5, 28, 12, 0, 0, 0, time.UTC)

	writeSnapshotDiscoveryFixture(t, cache,
		testDiscoverySourceName("lmstudio-dead", "lmstudio-dead", deadURL, "lmstudio-dead"),
		capturedAt,
		[]string{modelID},
	)
	writeSnapshotDiscoveryFixture(t, cache,
		testDiscoverySourceName("vidar", "vidar", vidarURL, "vidar"),
		capturedAt,
		[]string{modelID},
	)

	catalog := loadRoutingFixtureCatalog(t, `
version: 5
generated_at: 2026-05-28T00:00:00Z
catalog_version: test
policies:
  default:
    min_power: 1
    max_power: 10
    allow_local: true
models:
  mlx-community/Qwen3.6-27B-8bit:
    family: qwen
    status: active
    power: 7
    context_window: 32768
    surfaces:
      embedded-openai: mlx-community/Qwen3.6-27B-8bit
`)
	t.Cleanup(replaceRoutingCatalogForTest(t, catalog))

	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"lmstudio-dead": {
				Type:           "rapid-mlx",
				BaseURL:        deadURL,
				ServerInstance: "lmstudio-dead",
				Model:          modelID,
			},
			"vidar": {
				Type:           "rapid-mlx",
				BaseURL:        vidarURL,
				ServerInstance: "vidar",
				Model:          modelID,
			},
		},
		names:       []string{"lmstudio-dead", "vidar"},
		defaultName: "lmstudio-dead",
	}

	svc := newResolveRouteProbeTestService(t, sc, func(_ context.Context, provider, _ string) bool {
		t.Fatalf("route hot path invoked aliveness prober for %s", provider)
		return false
	})

	now := time.Now().UTC()
	svc.providerProbe.RecordProbe("lmstudio-dead", "", false, now)
	svc.providerProbe.RecordProbe("vidar", "", true, now)

	dec, err := svc.ResolveRoute(context.Background(), RouteRequest{})
	if err != nil {
		t.Fatalf("ResolveRoute: %v", err)
	}
	if dec == nil {
		t.Fatal("ResolveRoute returned nil decision")
	}

	// Should pick vidar (reachable), NOT lmstudio-dead (dead default).
	if dec.Provider != "vidar" {
		t.Fatalf("decision.Provider=%q, want vidar; decision=%#v", dec.Provider, dec)
	}
}

